        opened=', '.join(towns.iloc[i].name_original for i,v in enumerate(r['plan']['open_years']) if v==y)
        bought=sum(a['year']==y for a in r['plan']['aircraft']);b=r['budget'][y-1]
        investment.append([y,opened,bought,nf(r['annual_completed'][y-1]),f'{b["spend_rub"]/1e6:.3f}',f'{b["carry_rub"]/1e6:.3f}'])
